"""The verdict twin of every assertion protocol, generated by `scripts/generate_check_protocols.py`.

Do not edit.  `check()` hands back the twin of the view it was reached from, so an assertion asked for
a verdict is checked against the same value type it would be checked against normally:
`assert_that(1).check().starts_with("x")` is a type error rather than a runtime one.

Only operations that reach a verdict appear.  A pivot or a configurer has none to report, and both
proxies refuse them at runtime; see `assertpy/_engine/_operations.py`.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    import datetime
    import re
    from collections.abc import Callable, Hashable, Iterable, Mapping, Sized
    from pathlib import Path
    from typing import Any, Literal, Protocol, SupportsFloat, SupportsIndex, TypeVar, overload

    from typing_extensions import TypeIs

    from .._matcher_impls import ClassInfo, ExceptionInfo
    from ..errors import AssertionOutcome
    from ..matchers import Matcher
    from ._compat import Self
    from ._introspection import MappingLike

    # the type variables come from the module these twins mirror, so the two cannot disagree about a binding
    from ._typing import (
        _U,
        _ArrayT_co,
        _CapableT,
        _FrameT_co,
        _Holding,
        _Landed,
        _ObjectAssertion,
        _Other,
        _P_co,
        _T_co,
    )

    _KeySpecs = Hashable | list[Hashable] | set[Hashable] | frozenset[Hashable]

    _E = TypeVar("_E")
    # a verdict reads no exception back, so the twin's is covariant where the view's is not
    _Exc_co = TypeVar("_Exc_co", bound=BaseException, covariant=True)
    _N = TypeVar("_N", int, float)
    _K = TypeVar("_K")
    _V = TypeVar("_V")
    _B_co = TypeVar("_B_co", bytes, bytearray, covariant=True)
    _U2 = TypeVar("_U2")
    _U3 = TypeVar("_U3")
    _Number = SupportsFloat

    class _CheckMembershipAssertion(Protocol):
        """The verdict twin of `_MembershipAssertion`."""

        def is_subset_of(self, *supersets: object, allow_empty: bool = ...) -> AssertionOutcome: ...
        @property
        def not_(self) -> Self: ...

